101: /**
102:  * The modal the user is looking at: the frontmost one that isn't on its way out. Modals being torn
103:  * down are skipped rather than counted, since their frames are already gone — counting them would
104:  * leave the modal underneath hidden behind nothing until they finally left the stack.
105:  */
106: function frontmostModal(modalStack: Array<ModalInstance>) {
107:   return modalStack.find((instance) => !isClosing(instance));
108: }
109: 
110: /**
111:  * Only the frontmost modal is shown; the ones it was opened over stay in the DOM behind it. Applied
112:  * both as the stack changes and as a frame is inserted, since a frame inserted after the last
113:  * change to the stack would otherwise never be told.
114:  */
115: function applyModalVisibility(instance: ModalInstance, isFrontmost: boolean) {
116:   if (instance.container) {
117:     instance.container.style.visibility = isFrontmost ? 'unset' : 'hidden';
118:   }
119: }
120: 
121: const original = window.getComputedStyle(document.body).overflow;
122: 
123: function handleModalStateUpdate({ modalStack, modalContainer }: ModalState) {
124:   if (!modalContainer) {
125:     return;
126:   }
127: 
128:   if (modalStack.length) {
129:     // ensure the container is visible
130:     if (!modalContainer.style.visibility) {
131:       addEventListener('keydown', handleEscKey);
132:       document.body.style.overflow = 'hidden';
133:       modalContainer.style.visibility = 'unset';
134:     }
135: 
136:     // Stable across the pass below: the only states it changes are `NEW` to `MOUNTING` and
137:     // `TO_BE_DELETED` to `DELETED`, neither of which moves a modal in or out of the running.
138:     const frontmost = frontmostModal(modalStack);
139: 
140:     modalStack.forEach((instance) => {
141:       switch (instance.state) {
142:         case 'NEW': {
143:           const modalFrame = createModalFrame({ size: instance.props?.size ?? 'md' });
144:           instance.container = modalFrame;
145:           instance.state = 'MOUNTING';
146: 
147:           renderModalIntoDOM(modalFrame, instance.modalName, instance.props).then(
148:             (parcel) => {
149:               // Release the parcel if it's been closed while mounting
150:               if (isClosing(instance)) {
151:                 unmountModalParcel(instance.modalName, parcel);
152:                 return;
153:               }
154: 
155:               if (!parcel) {
156:                 // `renderModalIntoDOM` only returns without one when it had nowhere to render it,
157:                 // which it has already reported.
158:                 closeInstance(instance);
159:                 return;
160:               }
161: 
162:               instance.parcel = parcel;
163:               modalContainer.prepend(modalFrame);
164:               // The stack decides which modal is frontmost, not the DOM order this prepend just
165:               // established: another modal opened while this one loaded belongs on top of it.
166:               applyModalVisibility(instance, frontmostModal(modalStore.getState().modalStack) === instance);
167: 
168:               // The parcel is handed back before it has mounted, so this is where the modal is
169:               // really on screen.
170:               parcel.mountPromise.then(
171:                 () => {
172:                   if (!isClosing(instance)) {
173:                     instance.state = 'MOUNTED';
174:                   }
175:                 },
176:                 (err) => {
177:                   reportError(err);
178:                   instance.parcel = null;
179:                   closeInstance(instance);
180:                 },
181:               );
182:             },
183:             (err) => {
184:               // Nothing is chained to this, so without a handler a modal that fails to load is
185:               // only an unhandled rejection — and its instance holds the overlay open over a
186:               // page the user can no longer reach.
187:               reportError(err);
188:               closeInstance(instance);
189:             },
190:           );
191:           break;
192:         }
193: 
194:         // A frame is inserted as soon as the parcel exists, which is before it has mounted, so a
195:         // modal opened over one still mounting has to hide it just the same.
196:         case 'MOUNTING':
197:         case 'MOUNTED':
198:           applyModalVisibility(instance, instance === frontmost);
199:           break;
200: 
201:         case 'TO_BE_DELETED':
202:           instance.state = 'DELETED';
203:           instance.onClose();
204:           unmountModalParcel(instance.modalName, instance.parcel);
205:           instance.container?.remove();
206:           setTimeout(() => {
207:             // Read now rather than closed over: modals opened since this was scheduled are in the
208:             // store's stack but not in the one this pass saw, and would be dropped with it.
209:             const current = modalStore.getState();
210: 
211:             modalStore.setState({
212:               ...current,
213:               modalStack: current.modalStack.filter((x) => x !== instance),
214:             });
215:           }, 0);
216:           break;
217:       }
218:     });
219:   } else {
220:     modalContainer.style.removeProperty('visibility');
221:     document.body.style.overflow = original;
222:     removeEventListener('keydown', handleEscKey);
223:   }
224: }
225: 
226: function openInstance(instance: ModalInstance) {
227:   const state = modalStore.getState();
228:   const modalStack = [instance, ...state.modalStack];
229: 
230:   modalStore.setState({
231:     ...state,
232:     modalStack,
233:   });
234: }
